SELECT *
FROM yy_schedule
WHERE doc_id = #{docId}
  AND work_date = #{workDate}

SELECT s.*
FROM yy_schedule s
         JOIN yy_doctor d ON d.id = s.doc_id
WHERE d.dept_id = #{deptId}
  AND s.work_date = #{workDate}
ORDER BY s.doc_id

mapper.update:
UPDATE yy_schedule
SET available_num = available_num + #{num}
WHERE id = #{id}
